/**
 * The owner's taste, as fixed rules over the library: which genres, decades
 * and original languages their titles lean to, weighted by how strongly each
 * title says "I like this". It orders YOU MIGHT LIKE. Nothing here is
 * generated by a model; the same rows always give the same profile.
 *
 * Discover's answers count against: Not interested fully, a skip a quarter,
 * for the answers that carry the title's facts (see `answerTasteTitles`).
 */

import { discoveryKey, mediaOf, type DiscoveryMedia } from './discovery';
import { parseKey, yearOf, type DismissalAnswers } from './discovery-answers';
import { libraryStatus, visibleLibraryFor } from './library-state';
import type { FavouriteItem, WatchlistItem } from './WatchlistContext';

/** TMDB's genre names, films' ids. Series ids are mapped onto these first. */
export const GENRE_NAMES: Readonly<Record<number, string>> = {
  28: 'Action', 12: 'Adventure', 16: 'Animation', 35: 'Comedy', 80: 'Crime',
  99: 'Documentary', 18: 'Drama', 10751: 'Family', 14: 'Fantasy', 36: 'History',
  27: 'Horror', 10402: 'Music', 9648: 'Mystery', 10749: 'Romance', 878: 'Science Fiction',
  10770: 'TV Movie', 53: 'Thriller', 10752: 'War', 37: 'Western',
  10763: 'News', 10764: 'Reality', 10766: 'Soap', 10767: 'Talk',
};
/** Series genres that are two film genres in one, or a film genre renamed. */
const SERIES_GENRES: Readonly<Record<number, readonly number[]>> = {
  10759: [28, 12], // Action & Adventure
  10765: [878, 14], // Sci-Fi & Fantasy
  10768: [10752], // War & Politics
  10762: [10751], // Kids
};

/** A title's genres in films' ids, each once. */
export function tasteGenres(ids: readonly number[] | null | undefined): number[] {
  return [...new Set((ids ?? []).flatMap((id) => SERIES_GENRES[id] ?? [id]))];
}

/** How strongly a title says "I like this"; see `titleWeight`. */
export interface TasteSignal {
  /**
   * The title's `libraryStatus`, or null for a favourite that is not in the
   * library.
   */
  status: string | null;
  /** Personal rating, 0.5 to 10. */
  rating?: number | null;
  favourite: boolean;
}

/** Seen, or part-seen: a series between seasons or waiting on a return counts. */
const SEEN_STATUSES = new Set(['Watched', 'Completed', 'Caught up', 'Watching', 'Between seasons']);

/**
 * The weight of one title. A rating says the most, so it replaces what the
 * status says: 8 and up is 3, 6 and up 1.5, under 6 is -2. Without one,
 * seen or being watched is 1, saved to watch a quarter of that, stopped
 * watching -1, and hidden 0 (hiding is about privacy, not taste). A
 * favourite adds 2. Saved counts for little because a backlog runs to
 * hundreds of mostly new releases: at half a watch, 1,021 saved films
 * outweighed 379 watched ones on 2026-11-22 and named Drama and the 2020s,
 * which the watched films do not lean to.
 */
export function titleWeight(signal: TasteSignal): number {
  let weight = 0;
  if (signal.rating != null) weight = signal.rating >= 8 ? 3 : signal.rating >= 6 ? 1.5 : -2;
  else if (signal.status && SEEN_STATUSES.has(signal.status)) weight = 1;
  else if (signal.status === 'To Watch') weight = 0.25;
  else if (signal.status === 'Stopped watching') weight = -1;
  return weight + (signal.favourite ? 2 : 0);
}

export interface TasteTitle {
  media: DiscoveryMedia;
  genreIds?: readonly number[] | null;
  /** Release year. */
  year?: number | null;
  language?: string | null;
  weight: number;
}

/** Per dimension, each value's like share less part of its dislike share. */
export interface TasteProfile {
  genre: ReadonlyMap<number, number>;
  decade: ReadonlyMap<number, number>;
  language: ReadonlyMap<string, number>;
}

export const EMPTY_TASTE: TasteProfile = { genre: new Map(), decade: new Map(), language: new Map() };

/**
 * The weighted titles the profile is built from: every library title the
 * viewer can see (a visitor's leaves out hidden and stopped titles), with its
 * status, rating and whether it is a favourite, and each favourite not among
 * them on its own (the favourites table keeps genres and language but no
 * year; favourites are public).
 */
export function libraryTasteTitles(
  watchlist: readonly WatchlistItem[],
  favourites: readonly FavouriteItem[],
  isAdmin: boolean,
  today = new Date(),
): TasteTitle[] {
  const library = visibleLibraryFor([...watchlist], isAdmin);
  const favouriteKeys = new Set(favourites.filter((item) => item.tmdb_id).map((item) => discoveryKey(item.media_type, item.tmdb_id!)));
  const libraryKeys = new Set<string>();
  const titles = library.map((item): TasteTitle => {
    const key = item.tmdb_id ? discoveryKey(mediaOf(item), item.tmdb_id) : null;
    if (key) libraryKeys.add(key);
    return {
      media: mediaOf(item),
      genreIds: item.genre_ids,
      year: yearOf(item.year ?? item.release_date),
      language: item.original_language,
      weight: titleWeight({ status: libraryStatus(item, today), rating: item.personal_rating, favourite: key != null && favouriteKeys.has(key) }),
    };
  });
  for (const item of favourites) {
    if (item.tmdb_id && libraryKeys.has(discoveryKey(item.media_type, item.tmdb_id))) continue;
    titles.push({ media: item.media_type, genreIds: item.facts?.genre_ids, language: item.facts?.original_language, weight: titleWeight({ status: null, favourite: true }) });
  }
  return titles;
}

/**
 * Discover's answers as titles the profile counts against: Not interested
 * -1, a skip -0.25 (a no to a page, not to the title). Only answers that
 * carry the title's facts count, and not for a title in the library or the
 * favourites, which say more about it than the answer does. A title from
 * this year or later counts for its genres and language but not its decade:
 * COMING SOON shows only those, so turning them down says what was shown.
 */
export function answerTasteTitles(answers: DismissalAnswers, inLibrary: ReadonlySet<string>, today = new Date()): TasteTitle[] {
  const titles: TasteTitle[] = [];
  for (const [key, answer] of answers) {
    const parsed = parseKey(key);
    if (!answer.facts || !parsed || inLibrary.has(key)) continue;
    const { year } = answer.facts;
    titles.push({
      media: parsed.media,
      genreIds: answer.facts.genreIds,
      year: year != null && year < today.getFullYear() ? year : null,
      language: answer.facts.language,
      weight: answer.reason === 'not_interested' ? -1 : -0.25,
    });
  }
  return titles;
}

/**
 * Everything the profiles are built from: the library's titles and the
 * answers about titles outside it.
 */
export function tasteTitles(
  watchlist: readonly WatchlistItem[],
  favourites: readonly FavouriteItem[],
  answers: DismissalAnswers,
  isAdmin: boolean,
  today = new Date(),
): TasteTitle[] {
  const inLibrary = new Set<string>();
  for (const item of watchlist) if (item.tmdb_id) inLibrary.add(discoveryKey(mediaOf(item), item.tmdb_id));
  for (const item of favourites) if (item.tmdb_id) inLibrary.add(discoveryKey(item.media_type, item.tmdb_id));
  return [...libraryTasteTitles(watchlist, favourites, isAdmin, today), ...answerTasteTitles(answers, inLibrary, today)];
}

/**
 * How much a dislike share counts against a like share, at most. Below 1
 * because what you turn down is drawn from what you are shown, and you are
 * shown what is near your taste.
 */
export const DISLIKE_WEIGHT = 0.5;
/**
 * The dislike weight at which dislikes count half of `DISLIKE_WEIGHT`. A
 * share of one answer is as large as a share of hundreds, so a few answers
 * (after a reset, say) barely move the profile; hundreds count almost fully.
 */
export const DISLIKE_PRIOR = 20;

const decadeOf = (year?: number | null) => (year && Number.isFinite(year) ? Math.floor(year / 10) * 10 : null);

/**
 * The profile from weighted titles. Likes and dislikes are counted apart:
 * each value's share of the liking in its dimension, less `DISLIKE_WEIGHT`
 * times its share of the disliking, scaled down while there is little
 * disliking (see `DISLIKE_PRIOR`). Raw sums would let a thousand turned-down
 * suggestions swamp the library, and since suggestions come from what you
 * like, they would mark your favourite genres down most. As shares, a genre
 * counts against you only when it is more than twice as much of what you
 * turn down as of what you like. A title's weight is split between its
 * genres, so one tagged with five genres counts no more than one tagged with
 * one; decade and language each take the whole weight. Each dimension's
 * shares are of the titles that have it, so a favourite without a year does
 * not thin out the decades.
 */
export function buildTasteProfile(titles: readonly TasteTitle[]): TasteProfile {
  const sides = { like: newSide(), dislike: newSide() };
  for (const title of titles) {
    if (!title.weight) continue;
    const side = title.weight > 0 ? sides.like : sides.dislike;
    const weight = Math.abs(title.weight);
    side.total += weight;
    const genres = tasteGenres(title.genreIds);
    for (const id of genres) add(side.genre, id, weight / genres.length);
    const d = decadeOf(title.year);
    if (d != null) add(side.decade, d, weight);
    if (title.language) add(side.language, title.language, weight);
  }
  if (sides.like.total === 0 && sides.dislike.total === 0) return EMPTY_TASTE;
  const dislikeWeight = DISLIKE_WEIGHT * (sides.dislike.total / (sides.dislike.total + DISLIKE_PRIOR));
  const contrast = <K>(likes: Map<K, number>, dislikes: Map<K, number>) => {
    const out = new Map<K, number>();
    const likeTotal = sum(likes);
    const dislikeTotal = sum(dislikes);
    for (const [key, value] of likes) out.set(key, value / likeTotal);
    for (const [key, value] of dislikes) out.set(key, (out.get(key) ?? 0) - dislikeWeight * (value / dislikeTotal));
    return out;
  };
  return {
    genre: contrast(sides.like.genre, sides.dislike.genre),
    decade: contrast(sides.like.decade, sides.dislike.decade),
    language: contrast(sides.like.language, sides.dislike.language),
  };
}

interface Side { total: number; genre: Map<number, number>; decade: Map<number, number>; language: Map<string, number> }
const newSide = (): Side => ({ total: 0, genre: new Map(), decade: new Map(), language: new Map() });
const add = <K>(map: Map<K, number>, key: K, value: number) => map.set(key, (map.get(key) ?? 0) + value);
const sum = (map: ReadonlyMap<unknown, number>) => {
  let total = 0;
  for (const value of map.values()) total += value;
  return total;
};

/**
 * One profile for films and one for series: a library's series can lean to
 * Drama while its films lean to Action, and one blended profile would rank
 * drama films for someone who rarely watches them.
 */
export interface TasteProfiles { movie: TasteProfile; tv: TasteProfile }

export function buildTasteProfiles(titles: readonly TasteTitle[]): TasteProfiles {
  return {
    movie: buildTasteProfile(titles.filter((title) => title.media === 'movie')),
    tv: buildTasteProfile(titles.filter((title) => title.media === 'tv')),
  };
}

/**
 * A value against the dimension's strongest, liked or disliked, so every
 * part runs from -1 to 1 however small the profile is, and a value just
 * under zero stays just under zero.
 */
const relative = <K>(map: ReadonlyMap<K, number>, key: K | null | undefined) => {
  const value = key == null ? 0 : map.get(key) ?? 0;
  if (value === 0) return 0;
  let strongest = 0;
  for (const v of map.values()) strongest = Math.max(strongest, Math.abs(v));
  return value / strongest;
};

/**
 * How well a title fits the profile: its genres' mean, at 60%, then its
 * decade and its original language at 20% each, every part measured against
 * the profile's strongest value in that dimension. Higher fits better; a
 * title the profile knows nothing about scores 0.
 */
export function tasteScore(
  profile: TasteProfile,
  title: { genre_ids?: readonly number[] | null; year?: number | null; original_language?: string | null },
): number {
  const genres = tasteGenres(title.genre_ids);
  const genrePart = genres.length === 0 ? 0 : genres.reduce((sum, id) => sum + relative(profile.genre, id), 0) / genres.length;
  return 0.6 * genrePart + 0.2 * relative(profile.decade, decadeOf(title.year)) + 0.2 * relative(profile.language, title.original_language);
}

export interface TasteSummary {
  genres: string[];
  decade: string | null;
  languages: string[];
  /** Up to two genres that count against, most first. */
  avoids: string[];
}

/** At least this share of the weight before a decade or language is named. */
const SUMMARY_MIN_SHARE = 0.1;
/** How far below zero a genre must be before the summary says you avoid it. */
const SUMMARY_MIN_DISLIKE = 0.02;

/**
 * The profile in words: its three strongest named genres, its strongest
 * decade, and up to two languages with a tenth of the weight or more. Null
 * when there is nothing to say.
 */
export function tasteSummary(profile: TasteProfile, languageName: (code: string) => string): TasteSummary | null {
  const top = <K>(map: ReadonlyMap<K, number>, n: number, min = Number.MIN_VALUE) =>
    [...map].filter(([, value]) => value >= min).sort(([a, x], [b, y]) => y - x || String(a).localeCompare(String(b), 'en')).slice(0, n).map(([key]) => key);
  const genres = top(profile.genre, 3).map((id) => GENRE_NAMES[id]).filter((name): name is string => Boolean(name));
  const [decade] = top(profile.decade, 1, SUMMARY_MIN_SHARE);
  const languages = top(profile.language, 2, SUMMARY_MIN_SHARE).map(languageName);
  const avoids = [...profile.genre]
    .filter(([, value]) => value <= -SUMMARY_MIN_DISLIKE)
    .sort(([a, x], [b, y]) => x - y || a - b)
    .slice(0, 2)
    .map(([id]) => GENRE_NAMES[id])
    .filter((name): name is string => Boolean(name));
  if (genres.length === 0) return null;
  return { genres, decade: decade != null ? `${decade}s` : null, languages, avoids };
}
